173→          | const ANYWHERE = ['merde', 'putain', 'pute', 'salope', 'connard', 'connasse', 'encule', 'enculer', 'batard', 'bordel', 'couille', 'chier', 'nichon', 'branle', 'bouffon', 'abruti', 'debile', 'cretin', 'idiot', 'pouffiasse', 'fuck', 'shit', 'bitch', 'bastard', 'dick', 'cock', 'pussy', 'slut', 'whore', 'cunt', 'asshole', 'bollock', 'bugger', 'wanker', 'stupid', 'dumb', 'hitler', 'drogue', 'cocaine', 'weed', 'beer', 'biere', 'vodka', 'whisky'];
174→          | const LOOK_ALIKE = { 0: 'o', 1: 'i', 3: 'e', 4: 'a', 5: 's', 7: 't', 8: 'b', '@': 'a', $: 's', '€': 'e', '!': 'i', '|': 'i' };
175→          | function plainLetters(s) {
176→          |   return String(s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().split('').map((ch) => LOOK_ALIKE[ch] || ch).join('');
177→          | }
178→          | function rude(s) {
179→          |   const plain = plainLetters(s), joined = plain.replace(/[^a-z]/g, ''), squeezed = joined.replace(/(.)\1+/g, '$1');
180→          |   const words = plain.split(/[^a-z]+/).filter(Boolean);
181→          |   if (words.some((x) => ALONE.includes(x) || ALONE.includes(x.replace(/(.)\1+/g, '$1')))) return true;
182→          |   return ANYWHERE.some((bad) => joined.includes(bad) || squeezed.includes(bad));
183→          | }
184→          | const NAME_CHARS = /^[\p{L}\p{N} '’\-.,!?&()«»“”:]*$/u;
185→          | function cleanName(s, max) {
186→          |   const name = String(s === undefined || s === null ? '' : s).normalize('NFC').replace(/\s+/g, ' ').trim();
187→          |   if (!name) return '';
188→          |   if (name.length > (max || 30) || !NAME_CHARS.test(name) || rude(name)) return null;
189→          |   return name;
190→          | }
191→          | function checkChange(table, rowId, fields) {
192→          |   const T = TABLES[table];
193→          |   if (!T) return { ok: false, reason: 'badTable' };
194→          |   if (!fields || typeof fields !== 'object' || Array.isArray(fields)) return { ok: false, reason: 'badFields' };
195→          |   const id = T.one ? 'row' : String(rowId || '');
196→          |   const exists = T.one || (KNOWN[table] || []).includes(id);
197→          |   if (!exists) {
198→          |     if (!T.add) return { ok: false, reason: 'cannotAdd' };
199→          |     if (!/^[a-z][a-zA-Z0-9]{2,19}$/.test(id) || ['constructor', 'prototype', 'toString', 'valueOf'].includes(id)) return { ok: false, reason: 'badId' };
200→          |   }
201→          |   const allowed = exists ? T.edit : [...T.add, ...(T.optional || [])];
202→          |   const out = {};
203→          |   for (const [k, v] of Object.entries(fields)) {
204→          |     if (!allowed.includes(k)) return { ok: false, reason: 'badField' };
205→          |     if (k === 'fr' || k === 'en') {
206→          |       const name = cleanName(v, 30);
207→          |       if (!name) return { ok: false, reason: name === null ? 'nameRefused' : 'nameEmpty' };
208→          |       out[k] = name;
209→          |     } else if (k === 'icon') {
210→          |       if (!KNOWN.icons.includes(v)) return { ok: false, reason: 'badIcon' };
211→          |       out[k] = v;
212→          |     } else if (k === 'c') {
213→          |       if (v !== 4 && v !== 8) return { ok: false, reason: 'badCounts' };
214→          |       out[k] = v;
215→          |     } else if (k === 'st') {
216→          |       const list = String(v).split(' ').filter(Boolean);
217→          |       if (!(v === '*' || (list.length && list.every((x) => KNOWN.styles.includes(x))))) return { ok: false, reason: 'badStyle' };
218→          |       out[k] = v === '*' ? '*' : list.join(' ');
219→          |     } else if (k === 'themes') {
220→          |       if (!Array.isArray(v) || v.length > 4 || !v.every((x) => KNOWN.themes.includes(x))) return { ok: false, reason: 'badTheme' };
221→          |       out[k] = [...new Set(v)];
222→          |     } else {
223→          |       const [lo, hi] = RANGES[k];
224→          |       if (typeof v !== 'number' || !Number.isInteger(v) || v < lo || v > hi) return { ok: false, reason: `range_${k}` };
225→          |       if ((k === 'dx' || k === 'dz') && v === 0) continue;
226→          |       out[k] = v;
227→          |     }
228→          |   }
229→          |   if (!exists) for (const k of T.add) if (out[k] === undefined) return { ok: false, reason: 'missing' };
230→          |   if (Object.keys(out).length === 0) return { ok: false, reason: 'nothing' };
231→          |   return { ok: true, fields: out, isNew: !exists };
232→          | }
233→          | 
234→          | // ---- the change itself: only a grown-up, only what the checker above lets through ----
235→          | if (Inputs.rows === undefined || Inputs.roles === undefined) return;
236→          | const refuse = (reason) => { Outputs.reason = reason; Outputs.refused(); };
237→          | if (!(Inputs.roles || []).includes('grownup')) return refuse('notGrownup');
238→          | let fields = Inputs.fields;
239→          | if (typeof fields === 'string') { try { fields = JSON.parse(fields); } catch (e) { fields = null; } }
240→          | if (!fields || typeof fields !== 'object' || Array.isArray(fields)) return refuse('badFields');
241→          | const table = String(Inputs.table || '');
242→          | if (!TABLES[table]) return refuse('badTable');
243→          | const rowId = TABLES[table].one ? 'row' : String(Inputs.rowId || '');
244→          | const get = (o, k) => (o && typeof o.get === 'function' ? o.get(k) : o && o[k]);
245→          | const old = (Inputs.rows || []).find((r) => get(r, 'table') === table && get(r, 'rowId') === rowId);
246→          | let before = {};
247→          | if (old) { try { before = JSON.parse(get(old, 'fields')) || {}; } catch (e) { before = {}; } }
248→          | const result = checkChange(table, rowId, { ...before, ...fields });
249→          | if (!result.ok) return refuse(result.reason);
250→          | Outputs.table = table;
251→          | Outputs.rowId = rowId;
252→          | Outputs.fieldsJson = JSON.stringify(result.fields);
253→          | Outputs.existingId = old ? get(old, 'id') || old.id : '';
254→          | if (old) Outputs.update(); else Outputs.create();
255→        comment: The same checker as the browser's scripts/settings/check.js (generated from tools/check.src.js by tools/sync-check.mjs): cloud functions cannot use script files yet, so it is pasted here.
