335→    dp_fn: JavaScriptFunction "What the press changes" {uses: "game/dispatch,game/actions,game/save,game/text,view/run,view/common,view/formation,view/prep,settings/check,rules/data,rules/engine,rules/plan"}
336→        inputs: save, words, ui, res, live, act, arg, stage
337→        outputs: save: object, saveChanged: signal, ui: object, uiChanged: signal, res: object, resChanged: signal, live: object, liveChanged: signal, toast: object, toastChanged: signal
338→        run on value change OFF: act, arg, save, ui, res, live, words, stage
339→        functionScript:
340→          | if (!Inputs.save) return;
341→          | const w = Scripts.text.words(Inputs.words || [], Inputs.save.lang || 'fr');
342→          | const ui = { ...(Inputs.ui || {}), res: Inputs.res || null, live: Inputs.live || null };
343→          | const r = Scripts.dispatch.dispatch(Inputs.act, Inputs.arg, Inputs.save, ui, w, Inputs.stage) || {};
344→          | if (r.save) { Outputs.save = r.save; Outputs.saveChanged(); }
345→          | if (r.ui) {
346→          |   const { res, live, ...patch } = r.ui;
347→          |   if ('res' in r.ui) { Outputs.res = res; Outputs.resChanged(); }
348→          |   if ('live' in r.ui) { Outputs.live = live; Outputs.liveChanged(); }
349→          |   if (Object.keys(patch).length) { Outputs.ui = patch; Outputs.uiChanged(); }
350→          | }
351→          | if (r.toast) { Outputs.toast = { text: r.toast, n: Date.now() }; Outputs.toastChanged(); }
