        4→const { RULES, NUMBERS, MOVES, MAX_MOVES, OUTFITS, HAIRS, SHOES, ACCS, PIECES, LOGE, SNACKS, UPGRADES } = use('rules/data');
        5→const { clamp, isOwned, fits, footprint, routineInfo, danceOf, stageOf } = use('rules/engine');
        6→const { pickedNum } = use('view/common');
        7→const { geometry } = use('view/formation');
        8→const { foodPrice } = use('view/prep');
