       10→
       11→const copy = (o) => JSON.parse(JSON.stringify(o));
       12→const MAX_BLOCKS = 8, MAX_CHAIN = 60;
       13→
       14→// buying: a price in stars, kept for good
       15→function buy(save, kind, id, w) {
       16→  const price = kind === 'up' ? UPGRADES[id].price : kind === 'food' ? foodPrice(id) : (({ outfit: OUTFITS, hair: HAIRS, shoes: SHOES, acc: ACCS, piece: PIECES, snack: SNACKS })[kind][id].price || 0);
       17→  const name = kind === 'up' ? w.nm(UPGRADES[id]) : kind === 'food' ? w(`foods_${id}`) : w.nm(({ outfit: OUTFITS, hair: HAIRS, shoes: SHOES, acc: ACCS, piece: PIECES, snack: SNACKS })[kind][id]);
       18→  const sc = save.school;
       19→  if (sc.stars < price) return { ok: false, toast: w('notEnough') };
       20→  sc.stars -= price;
       21→  if (kind === 'up') sc.upgrades[id] = id === 'sieges' ? (sc.upgrades[id] || 0) + 1 : true;
       22→  else sc.owned[`${kind}:${id}`] = true;
       23→  if (kind === 'up' && id === 'logeXL') sc.logeCols = LOGE.colsBig;
       24→  if (kind === 'up' && id.startsWith('decor')) save.plan.backdrop = { decorForet: 'foret', decorMer: 'mer', decorVille: 'ville' }[id];
       25→  return { ok: true, toast: w('bought', name) };
       26→}
       27→
       28→/* ---------------- the programme ---------------- */
       29→function orderStep(save0, which, d) {
       30→  const save = copy(save0), P = save.plan;
       31→  if (which === 'start') P.start = clamp(P.start + d * 300, RULES.startMin, RULES.startMax);
